export type InstalledTarget = Readonly<{bundleId: 'com.apple.webapp'; nativePid: number}>;
const INSTALLED_CONTRACT = 'herdr-installed-contexts-v1';

export function installedContextContract(this: RemoteDebugger): string {
  if (this.selectApp !== selectApp) {
    throw new Error('Installed selector contract unavailable');
  }
  return INSTALLED_CONTRACT;
}

export function validateInstalledTarget(target: InstalledTarget): InstalledTarget {
  if (!target || Object.keys(target).sort().join(',') !== 'bundleId,nativePid' ||
      target.bundleId !== 'com.apple.webapp' || typeof target.nativePid !== 'number' ||
      !Number.isSafeInteger(target.nativePid) || target.nativePid <= 0 || target.nativePid > 9999999999) {
    throw new Error('Invalid installed target');
  }
  return Object.freeze({bundleId: 'com.apple.webapp', nativePid: target.nativePid});
}

function numericId(value: unknown): number | undefined {
  if (typeof value === 'number') {
    return Number.isSafeInteger(value) && value > 0 && value <= 9999999999 ? value : undefined;
  }
  if (typeof value !== 'string' || !/^PID:[1-9]\d{0,9}$/.test(value)) return undefined;
  return Number(value.slice(4));
}

function providerRole(bundleId: string | undefined): 'webapp' | 'service' | 'generic' | 'other' | 'unknown' {
  if (typeof bundleId !== 'string' || !bundleId) return 'unknown';
  if (bundleId === 'com.apple.webapp') return 'webapp';
  if (bundleId === SAFARI_VIEW_BUNDLE_ID) return 'service';
  if ([WEB_CONTENT_BUNDLE_ID, WEB_CONTENT_PROCESS_BUNDLE_ID, SAFARI_VIEW_PROCESS_BUNDLE_ID].includes(bundleId)) return 'generic';
  return 'other';
}

function providerHost(apps: AppDict, hostId: unknown, scope: InstalledTarget): boolean {
  const pid = numericId(hostId);
  if (!pid) return false;
  const host = apps[`PID:${pid}`];
  const native = apps[`PID:${scope.nativePid}`];
  const nativeValid = !native || (native.id === `PID:${scope.nativePid}` && !!native.installedIdentity && native.isActive &&
    providerRole(native.bundleId) === 'webapp' && (native.hostId === undefined || numericId(native.hostId) === scope.nativePid));
  if (pid === scope.nativePid) return nativeValid;
  // A service PID need not equal the native PID. Preserve the inspector's one-hop proxy relationship.
  return !!host && host.id === `PID:${pid}` && !!host.installedIdentity && host.isActive && ['webapp', 'service'].includes(providerRole(host.bundleId)) &&
    (host.hostId === undefined || (numericId(host.hostId) === scope.nativePid && nativeValid));
}

function installedReason(apps: AppDict, id: string, scope: InstalledTarget): string {
  const app = apps[id];
  if (!app || !app.isActive) return 'inactive';
  if (!app.installedIdentity) return 'unreported';
  if (!numericId(id) || app.id !== id) return 'malformed';
  const role = providerRole(app.bundleId);
  if (role === 'other' || role === 'unknown') return 'unsupported';
  if (app.hostId !== undefined && !numericId(app.hostId)) return 'malformed';
  if (app.hostId !== undefined && !providerHost(apps, app.hostId, scope)) return 'wrong-host';
  if (role === 'generic') {
    return app.isProxy === true && app.hostId !== undefined && !!apps[app.hostId] && providerHost(apps, app.hostId, scope)
      ? 'proxy' : 'unowned';
  }
  if (app.hostId !== undefined && numericId(app.hostId) !== scope.nativePid && app.isProxy !== true) return 'wrong-host';
  return app.hostId === undefined ? 'provider' : 'host';
}

function installedEligible(apps: AppDict, id: string, scope: InstalledTarget): boolean {
  return ['provider', 'host', 'proxy'].includes(installedReason(apps, id, scope));
}

function installedProof(apps: AppDict, id: string, scope: InstalledTarget, pages: Page[] = []): NonNullable<AppDict[string]['installedPageScope']> {
  const app = apps[id];
  return {nativePid: scope.nativePid, owner: app.installedIdentity!, host: app.hostId === undefined ? undefined : apps[app.hostId]?.installedIdentity,
    native: apps[`PID:${scope.nativePid}`]?.installedIdentity,
    pages: pages.map(page => {
      const host = apps[`PID:${numericId(page.hostId)}`];
      return {id: page.hostId, owner: host?.installedIdentity, host: host?.hostId === undefined ? undefined : apps[host.hostId]?.installedIdentity};
    })};
}

function sameInstalledProof(a: AppDict[string]['installedPageScope'], b: AppDict[string]['installedPageScope']): boolean {
  return !!a && !!b && a.nativePid === b.nativePid && a.owner === b.owner && a.host === b.host && a.native === b.native &&
    a.pages.length === b.pages.length && a.pages.every((page, index) =>
      page.id === b.pages[index].id && page.owner === b.pages[index].owner && page.host === b.pages[index].host);
}

function installedPageEligible(apps: AppDict, id: string, page: Page, scope: InstalledTarget): boolean {
  if (!installedEligible(apps, id, scope) || !sameInstalledProof(apps[id].installedPageScope, installedProof(apps, id, scope, apps[id].pageArray))) return false;
  return page.hostId === undefined || (numericId(page.hostId) !== undefined && providerHost(apps, page.hostId, scope));
}

function logInstalledCandidate(this: RemoteDebugger, apps: AppDict, id: string, scope: InstalledTarget): void {
  const app = apps[id];
  const reason = installedReason(apps, id, scope);
  const action = ['provider', 'host', 'proxy'].includes(reason) ? 'list' : 'skip';
  this.log.debug(`Installed candidate app=${numericId(id) ?? 0} host=${numericId(app?.hostId) ?? 0} native=${scope.nativePid} role=${providerRole(app?.bundleId)} reason=${reason} action=${action}`);
}

