export type InstalledTarget = Readonly<{bundleId: 'com.apple.webapp'; nativePid: number}>;

/** No device/inspector discovery: attest the loaded driver and selector, not just disk bytes. */
export function mobileInstalledContextContract(this: XCUITestDriver): {contract: string; selector: string} {
  if (this.mobileGetInstalledContexts !== mobileGetInstalledContexts ||
      this.getContextsAndViews !== getContextsAndViews || this.listWebFrames !== listWebFrames) {
    throw new Error('Installed driver contract unavailable');
  }
  const selector = new RemoteDebugger({log: this.log});
  const remote = this._remote ?? selector;
  if (typeof remote.installedContextContract !== 'function' || remote.installedContextContract !== selector.installedContextContract) {
    throw new Error('Installed selector contract unavailable');
  }
  return {contract: 'herdr-installed-contexts-v1', selector: remote.installedContextContract()};
}

export async function mobileGetInstalledContexts(this: XCUITestDriver, targetApp: InstalledTarget): Promise<Array<FullContext & {hostId?: number}>> {
  if (!targetApp || Object.keys(targetApp).sort().join(',') !== 'bundleId,nativePid' ||
      targetApp.bundleId !== 'com.apple.webapp' || typeof targetApp.nativePid !== 'number' ||
      !Number.isSafeInteger(targetApp.nativePid) || targetApp.nativePid <= 0 || targetApp.nativePid > 9999999999) {
    throw new errors.InvalidArgumentError('Invalid installed target');
  }
  const scope: InstalledTarget = Object.freeze({bundleId: 'com.apple.webapp', nativePid: targetApp.nativePid});
  mobileInstalledContextContract.call(this);
  const contexts = await this.getContextsAndViews(false, scope);
  return contexts.map(context => {
    const rawHost = (context.view as any)?.hostId;
    const hostId = typeof rawHost === 'number' ? rawHost :
      typeof rawHost === 'string' && /^PID:[1-9]\d{0,9}$/.test(rawHost) ? Number(rawHost.slice(4)) : undefined;
    return {
      id: context.id.toString(), title: context.view?.title, url: context.view?.url,
      bundleId: context.view?.bundleId,
      ...(typeof hostId === 'number' && Number.isSafeInteger(hostId) && hostId > 0 && hostId <= 9999999999 ? {hostId} : {}),
    };
  }) as Array<FullContext & {hostId?: number}>;
}

